function checkList<D>(rule: Rule<D>, list: readonly unknown[], data: D, parent: Path): Failure | null {
  const field: Path = { parent, step: rule.name };
  if (rule.min_count !== undefined && list.length < rule.min_count) return { path: pathText(field), rule: 'min_count' };
  if (rule.max_count !== undefined && list.length > rule.max_count) return { path: pathText(field), rule: 'max_count' };
  if (rule.unique === true && new Set(list.map(uniqueKey)).size !== list.length) return { path: pathText(field), rule: 'unique' };
  for (let i = 0; i < list.length; i += 1) {
    const failure = checkValue(rule, list[i], data, field, i);
    if (failure !== null) return failure;
  }
  return null;
}

function validateAt<D>(message: object, rules: readonly Rule<D>[], data: D, path: Path): Failure | null {
  const record = message as Readonly<Record<string, unknown>>;
  for (const rule of rules) {
    const value = record[rule.name];
    const failure = rule.repeated ? checkList(rule, value as readonly unknown[], data, path) : checkValue(rule, value, data, path, rule.name);
    if (failure !== null) return failure;
  }
  return null;
}

/** First failed field path and rule of a message, or null when the message passes. */
export function validate<D>(message: object, rules: readonly Rule<D>[], data: D, prefix: string): Failure | null {
  return validateAt(message, rules, data, prefix);
}
